\set ON_ERROR_STOP on
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(13);
INSERT INTO auth.users(id,email,email_confirmed_at) VALUES('16000000-0000-4000-8000-000000000001','pos@example.test',now()),('16000000-0000-4000-8000-000000000002','buyer@example.test',now());
INSERT INTO owners(id,email,phone) VALUES('16000000-0000-4000-8000-000000000001','pos@example.test','');
INSERT INTO restaurants(id,slug,name,owner_id,is_open,is_accepting_orders,customization_config)
VALUES('16000000-0000-4000-8000-000000000003','pos-pricing-paris','POS Pricing','16000000-0000-4000-8000-000000000001',true,true,'{"enabled":true,"base_price":8,"steps":[{"id":"base","required":true,"options":[{"id":"bread","price_modifier":1}]},{"id":"viande","required":true,"options":[{"id":"beef","price_modifier":2}]},{"id":"garniture","options":[{"id":"salad","price_modifier":0.5}]},{"id":"sauces","options":[{"id":"mayo","price_modifier":0.5}]},{"id":"accompagnement","options":[{"id":"fries","price_modifier":2,"portion_options":[{"id":"normale","price_modifier":0},{"id":"double","price_modifier":1}]}]},{"id":"supplements","options":[{"id":"cheese","price_modifier":1}]}]}');
CREATE TEMP TABLE pos_payload AS SELECT '{"restaurant_id":"16000000-0000-4000-8000-000000000003","customer_name":"POS Client","customer_phone":"","order_type":"sur_place","source":"pos","subtotal":17,"total":17,"items":[{"type":"custom","name":"Sandwich","quantity":1,"price":17,"customization_selection":{"base_id":"bread","viande_ids":["beef"],"garnitures":[{"option_id":"salad","level":"x2"}],"sauce_ids":["mayo"],"accompagnement":{"option_id":"fries","portion":"double"},"supplements":[{"option_id":"cheese","quantity":2}]}}]}'::jsonb payload;
SELECT set_config('request.jwt.claim.sub','16000000-0000-4000-8000-000000000001',true),set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
INSERT INTO customer_profiles(id,name,total_orders,total_spent) VALUES('16000000-0000-4000-8000-000000000001','POS Owner',0,0) ON CONFLICT(id) DO UPDATE SET total_orders=0,total_spent=0;
SELECT extensions.lives_ok($$SELECT place_order_once('16000000-0000-4000-8000-000000000004',(SELECT payload FROM pos_payload))$$,'owner POS customized order accepted at server price');
SELECT extensions.is((SELECT total FROM orders WHERE restaurant_id='16000000-0000-4000-8000-000000000003'),17::numeric,'POS selections use server modifiers');
SELECT extensions.throws_ok($$SELECT place_order_once('16000000-0000-4000-8000-000000000005',(SELECT payload || '{"total":1,"subtotal":1}' FROM pos_payload))$$,'22023','invalid_total','owner POS still cannot submit stale or forged totals');
SELECT extensions.throws_ok($$SELECT place_order_once('16000000-0000-4000-8000-000000000006',(SELECT jsonb_set(payload,'{items,0,customization_selection,base_id}','"missing"') FROM pos_payload))$$,'22023','invalid_total','unknown POS selection refused');
SELECT set_config('request.jwt.claim.sub','16000000-0000-4000-8000-000000000002',true),set_config('request.jwt.claims','{"sub":"16000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
SELECT extensions.throws_ok($$SELECT place_order_once('16000000-0000-4000-8000-000000000007',(SELECT payload FROM pos_payload))$$,'42501','pos_owner_required','public customer cannot impersonate POS');
SELECT extensions.is((SELECT count(*)::int FROM orders WHERE restaurant_id='16000000-0000-4000-8000-000000000003'),1,'refused POS requests do not create partial orders');
UPDATE restaurants SET out_of_stock_ingredients='["salad"]' WHERE id='16000000-0000-4000-8000-000000000003';
SELECT extensions.is(calculate_pos_custom_total('16000000-0000-4000-8000-000000000003','{"base_id":"bread","viande_ids":["beef"],"garnitures":[{"option_id":"salad","level":"non"}],"sauce_ids":[],"accompagnement":null,"supplements":[]}'),11::numeric,'unselected unavailable garnish does not block an order');
SELECT extensions.is(calculate_pos_custom_total('16000000-0000-4000-8000-000000000003','{"base_id":"bread","viande_ids":["beef"],"garnitures":[{"option_id":"salad","level":"oui"}],"sauce_ids":[],"accompagnement":null,"supplements":[]}'),NULL::numeric,'selected unavailable garnish is still refused');
UPDATE restaurants SET out_of_stock_ingredients='[]',customization_config='{"enabled":true,"base_price":8,"steps":[{"id":"viande","required":true,"max_selections":2,"options":[{"id":"beef","price_modifier":2},{"id":"chicken","price_modifier":3}]},{"id":"base","required":true,"options":[{"id":"bread","price_modifier":1,"allow_multi_meat":true}]}]}' WHERE id='16000000-0000-4000-8000-000000000003';
SELECT extensions.is(calculate_pos_custom_total('16000000-0000-4000-8000-000000000003','{"base_id":"bread","viande_ids":["beef","chicken"],"garnitures":[],"sauce_ids":[],"accompagnement":null,"supplements":[]}'),14::numeric,'multi-meat base allowance does not depend on step order');
UPDATE restaurants SET customization_config='{"enabled":true,"base_price":8,"steps":[{"id":"base","required":true,"options":[{"id":"bread","price_modifier":0}]},{"id":"accompagnement","options":[{"id":"fries","price_modifier":2,"portion_options":[{"id":"normale","price_modifier":1.5},{"id":"double","price_modifier":3}]}]}]}' WHERE id='16000000-0000-4000-8000-000000000003';
SELECT extensions.is(calculate_pos_custom_total('16000000-0000-4000-8000-000000000003','{"base_id":"bread","viande_ids":[],"garnitures":[],"sauce_ids":[],"accompagnement":{"option_id":"fries","portion":"normale"},"supplements":[]}'),11.5::numeric,'normal portion modifier uses the same canonical price as the POS');
SELECT extensions.ok((SELECT customer_user_id IS NULL FROM orders WHERE restaurant_id='16000000-0000-4000-8000-000000000003'),'POS does not bind walk-in customer to merchant account');
SELECT extensions.is((SELECT total_orders FROM customer_profiles WHERE id='16000000-0000-4000-8000-000000000001'),0,'POS does not increment merchant personal customer statistics');
SELECT extensions.is((SELECT total_spent FROM customer_profiles WHERE id='16000000-0000-4000-8000-000000000001'),0::numeric,'POS does not count takings as merchant personal spending');
SELECT * FROM extensions.finish();
ROLLBACK;
